 "content": "def transform(grid):
    """Composite the four 3-row panels by color priority: 5, 4, 8, then 2."""
    h = len(grid) // 4
    if h * 4 != len(grid):
        raise ValueError("expected four equal-height panels")
    width = len(grid[0])
    priority = {5: 4, 4: 3, 8: 2, 2: 1}
    out = [[0 for _ in range(width)] for _ in range(h)]
    for r in range(h):
        for c in range(width):
            candidates = [grid[layer * h + r][c] for layer in range(4)]
            out[r][c] = max(candidates, key=lambda v: priority.get(v, 0))
    return out
